ValidationRule.errorConditionFormula:
AND(
/* Only enforce when Status is changed to Eligible */
ISCHANGED(Status),
ISPICKVAL(Status, "Eligible"),

/* Block if ANY prerequisite is not met */
OR(

/* Priority Items still pending review */
Priority_Items_Pending_Review__c > 0,

/* Student District must be populated */
ISBLANK(Student_District_Id__c),

/* Residency restriction not met */
Residency_Restriction__c = TRUE,

/* Age / Grade inconsistency not approved */
AND(
Age_Inconsistency_Flag_c__c = TRUE,
NOT(
ISPICKVAL(
Age_Inconsistency_Review_Status__c,
"Exception Made"
)
)
)
)
)
